// Autoresponder processor with RFC 3834 anti-loop protection and branded signatures
const items = $input.all();
const results = [];

for (const item of items) {
  const json = item.json || {};
  const headers = json.headers || {};

  // 1. Identify recipient mailbox
  const deliveredTo = String(headers['delivered-to'] || '').toLowerCase();
  const toField = String(json.to?.text || json.to?.value?.[0]?.address || json.to || '').toLowerCase();
  const isOrderMailbox = deliveredTo.includes('order@') || toField.includes('order@') || (!deliveredTo.includes('team@') && !toField.includes('team@'));
  const mailboxEmail = isOrderMailbox ? 'order@erythro.ai' : 'team@erythro.ai';
  const mailboxRole = isOrderMailbox ? 'Customer Service Orders' : 'Customer Support & Operations Team';

  // 2. Extract sender email
  const rawFrom = json.from?.value?.[0]?.address || json.from?.text || json.from || headers['return-path'] || '';
  let fromAddress = String(rawFrom).trim().toLowerCase().replace(/^<|>$/g, '');
  const senderName = json.from?.value?.[0]?.name || json.fromName || (fromAddress.includes('@') ? fromAddress.split('@')[0] : '');

  // 3. Anti-loop filter (RFC 3834, bounce, no-reply, internal domain)
  const skipReasons = [];
  if (!fromAddress || !fromAddress.includes('@')) {
    skipReasons.push('invalid_from');
  }
  if (fromAddress.endsWith('@erythro.ai')) {
    skipReasons.push('internal_domain');
  }
  if (/no-?reply|mailer-daemon|postmaster|daemon|bounce|notifications?@/i.test(fromAddress)) {
    skipReasons.push('automated_sender');
  }

  // Check headers
  const autoSubmitted = String(headers['auto-submitted'] || '').toLowerCase();
  const precedence = String(headers['precedence'] || '').toLowerCase();
  const xAutoreply = String(headers['x-autoreply'] || '').toLowerCase();

  if (autoSubmitted && autoSubmitted !== 'no') {
    skipReasons.push('auto_submitted_header');
  }
  if (['bulk', 'junk', 'list', 'auto_reply'].includes(precedence)) {
    skipReasons.push('precedence_header');
  }
  if (xAutoreply === 'yes') {
    skipReasons.push('x_autoreply_header');
  }

  if (skipReasons.length > 0) {
    results.push({
      json: {
        skip: true,
        skipReasons,
        fromAddress,
        mailboxEmail
      }
    });
    continue;
  }

  // 4. Subject formatting
  const origSubject = (json.subject || '').trim();
  const replySubject = origSubject.toLowerCase().startsWith('re:') ? origSubject : `Re: ${origSubject || 'Your inquiry to Erythro.ai'}`;
  const messageId = json.messageId || json['message-id'] || headers['message-id'] || '';

  // 5. Signatures (Plaintext and HTML)
  const plainSignature =
`Best regards, 
${mailboxRole} 
Tel. +972505308305
Email: ${mailboxEmail}
URL: https://erythro.ai
----------------------------
Hi-Load Web Development & Ai Agents Automation`;

  const htmlSignature =
`<div style="margin-top: 24px; padding-top: 16px; border-top: 2px solid #333333; font-family: Arial, Helvetica, sans-serif; font-size: 14px; line-height: 1.5; color: #000000;">
  <p style="margin: 0 0 6px 0; font-size: 14px; font-weight: bold; color: #000000;">Best regards,<br>${mailboxRole}</p>
  <p style="margin: 0 0 4px 0; font-size: 14px; color: #000000;">Tel. <a href="tel:+972505308305" style="color: #0055cc; text-decoration: underline; font-weight: bold;">+972505308305</a></p>
  <p style="margin: 0 0 4px 0; font-size: 14px; color: #000000;">Email: <a href="mailto:${mailboxEmail}" style="color: #0055cc; text-decoration: underline; font-weight: bold;">${mailboxEmail}</a></p>
  <p style="margin: 0 0 10px 0; font-size: 14px; color: #000000;">URL: <a href="https://erythro.ai" style="color: #0055cc; text-decoration: underline; font-weight: bold;">https://erythro.ai</a></p>
  <div style="font-size: 12px; color: #333333; border-top: 1px dashed #666666; padding-top: 6px; font-weight: bold;">
    Hi-Load Web Development &amp; Ai Agents Automation
  </div>
</div>`;

  // 6. Message Body
  const greeting = senderName ? `Hello ${senderName},` : 'Hello,';
  const mainMessage = 'Thank you for contacting Erythro.ai. We have received your message, and our team is currently reviewing your request. We will contact you with more information within 2-6 business hours.';

  const textBody =
`${greeting}

${mainMessage}

${plainSignature}`;

  const htmlBody =
`<div style="background-color: #ffffff; color: #000000; font-family: Arial, Helvetica, sans-serif; font-size: 15px; line-height: 1.6; padding: 12px; max-width: 600px;">
  <p style="margin: 0 0 16px 0; font-size: 15px; color: #000000;">${greeting}</p>
  <p style="margin: 0 0 16px 0; font-size: 15px; color: #000000;">${mainMessage}</p>
  ${htmlSignature}
</div>`;

  results.push({
    json: {
      skip: false,
      to: fromAddress,
      from: `Erythro.ai <${mailboxEmail}>`,
      mailboxEmail,
      subject: replySubject,
      textBody,
      htmlBody,
      messageId,
      references: messageId
    }
  });
}

return results;
